import { createHash, randomBytes } from 'node:crypto';

/** A photo file kept in storage, with the moment it was stored (for the nightly cleanup, C-50). */
export type StoredFile = { key: string; storedAt: Date };

/**
 * Where photo files live (S3-compatible service in production, ADR-005). Keys are always
 * generated by the server (`newImageKey`), never built from client text (ASVS v5.0.0-5.3.2).
 */
export type ImageStorage = {
  put(key: string, bytes: Buffer): Promise<void>;
  /** The file, or null when it is absent. */
  get(key: string): Promise<Buffer | null>;
  /** Deletes the file; an absent file is no error. */
  delete(key: string): Promise<void>;
  /** Files whose key is greater than `after` (null: from the start), in key order. */
  listFiles(after: string | null, limit: number): Promise<StoredFile[]>;
};

export type ImageFormat = 'jpeg' | 'png' | 'webp';

/** Decodes and re-encodes photos so the stored file has no metadata (design section 12). */
export type ImageProcessor = {
  /** @throws {UnreadableImageError} when the bytes are not a readable jpeg, png or webp. */
  inspect(bytes: Buffer): Promise<{ format: ImageFormat; width: number; height: number }>;
  /** WebP bytes without any metadata; `vary` makes two outputs of the same bytes differ. */
  reencode(bytes: Buffer, options: { vary: boolean }): Promise<Buffer>;
};

/** The bytes are not a readable image. */
export class UnreadableImageError extends Error {
  constructor(message = 'Unreadable image') {
    super(message);
    this.name = 'UnreadableImageError';
  }
}

/** In-memory storage for tests and local runs; `clock` lets a test age a file. */
export class FakeImageStorage implements ImageStorage {
  private readonly files = new Map<string, { bytes: Buffer; storedAt: Date }>();

  constructor(private readonly clock: () => Date = () => new Date()) {}

  put(key: string, bytes: Buffer): Promise<void> {
    this.files.set(key, { bytes: Buffer.from(bytes), storedAt: this.clock() });
    return Promise.resolve();
  }

  get(key: string): Promise<Buffer | null> {
    const file = this.files.get(key);
    return Promise.resolve(file ? Buffer.from(file.bytes) : null);
  }

  delete(key: string): Promise<void> {
    this.files.delete(key);
    return Promise.resolve();
  }

  listFiles(after: string | null, limit: number): Promise<StoredFile[]> {
    const files = [...this.files.entries()]
      .filter(([key]) => after === null || key > after)
      .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
      .slice(0, limit)
      .map(([key, file]) => ({ key, storedAt: file.storedAt }));
    return Promise.resolve(files);
  }
}

const HEADER_LENGTH = 24;

function detectFormat(bytes: Buffer): ImageFormat | null {
  if (bytes.length >= 3 && bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff)
    return 'jpeg';
  if (bytes.length >= 4 && bytes.subarray(0, 4).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47])))
    return 'png';
  if (
    bytes.length >= 12 &&
    bytes.subarray(0, 4).toString('latin1') === 'RIFF' &&
    bytes.subarray(8, 12).toString('latin1') === 'WEBP'
  ) {
    return 'webp';
  }
  return null;
}

/**
 * Photo processor for tests: the format comes from the first bytes and the size from the PNG
 * header layout (width at bytes 16 to 19, height at 20 to 23, big-endian) for every format.
 * The output is WebP-shaped: the same 24-byte header, then a digest of the input bytes after
 * offset 24 (so nothing of the input's extra bytes survives), plus 8 random bytes with `vary`.
 */
export class FakeImageProcessor implements ImageProcessor {
  inspect(bytes: Buffer): Promise<{ format: ImageFormat; width: number; height: number }> {
    const format = detectFormat(bytes);
    if (format === null || bytes.length < HEADER_LENGTH) {
      return Promise.reject(new UnreadableImageError());
    }
    return Promise.resolve({
      format,
      width: bytes.readUInt32BE(16),
      height: bytes.readUInt32BE(20),
    });
  }

  async reencode(bytes: Buffer, options: { vary: boolean }): Promise<Buffer> {
    const { width, height } = await this.inspect(bytes);
    const digest = createHash('sha256').update(bytes.subarray(HEADER_LENGTH)).digest();
    const body = options.vary ? [digest, randomBytes(8)] : [digest];
    const header = Buffer.alloc(HEADER_LENGTH);
    header.write('RIFF', 0, 'latin1');
    header.write('WEBP', 8, 'latin1');
    header.write('FAKE', 12, 'latin1');
    header.writeUInt32BE(width, 16);
    header.writeUInt32BE(height, 20);
    const output = Buffer.concat([header, ...body]);
    output.writeUInt32LE(output.length - 8, 4);
    return output;
  }
}

const storageInstance = new FakeImageStorage();
const processorInstance = new FakeImageProcessor();

/** The one storage adapter; `IMAGE_DRIVER` accepts only `fake` until ADR-005 is accepted. */
export function getImageStorage(): ImageStorage {
  return storageInstance;
}

/** The one photo processor; `IMAGE_DRIVER` accepts only `fake` until ADR-005 is accepted. */
export function getImageProcessor(): ImageProcessor {
  return processorInstance;
}
